'use strict';
const audioFadeCurves={linear:'Linear',smooth:'Smooth',power:'Equal power',slow:'Slow start'};
function audioCurveValue(f,curve){f=clamp(f,0,1);return curve==='smooth'?f*f*(3-2*f):curve==='power'?Math.sin(f*Math.PI/2):curve==='slow'?f*f:f}
function audioBaseEnvelope(c,t){const fade=fadeDurations(c);return c.volume*normalizationGain(c)*Math.min(fade.in?audioCurveValue(t/fade.in,c.fadeInCurve):1,fade.out?audioCurveValue((c.duration-t)/fade.out,c.fadeOutCurve):1)}
envelopeAt=function(c,t){const value=audioBaseEnvelope(c,t);return c.role==='music'&&c.ducking!==false?value*duckFactorAt(c.start+t):value};
scheduleEnvelope=function(param,c,when,skip,length){if(length<=0)return;const count=Math.max(2,Math.min(200000,Math.ceil(length*100)+1)),values=new Float32Array(count),settings=duckSettings(),windows=c.role==='music'&&c.ducking!==false&&settings.enabled?narrationWindows():null;for(let i=0;i<count;i++){const at=skip+length*i/(count-1);values[i]=audioBaseEnvelope(c,at)*(windows?duckFactorAt(c.start+at,settings,windows):1)}param.setValueCurveAtTime(values,when,length)};
function crossfadeAudioClips(a,b,duration){if(!a||!b||a===b||a.locked||b.locked)throw Error('Choose two unlocked audio clips.');if(a.videoId||b.videoId)throw Error('Use a video transition for linked footage, or detach the sound first.');if(a.dialogueLineId||b.dialogueLineId)throw Error('Use Script overlap timing for arranged dialogue.');if(!Number.isFinite(duration)||duration<.05||duration>Math.min(a.duration,b.duration)||b.start<=a.start)throw Error('Choose a later clip and a fade shorter than both sounds.');const start=audioEnd(a)-duration;if(start<0||start+b.duration>totalDuration()+.001)throw Error('Keep the crossfade inside the project.');b.start=start;a.fadeOut=duration;a.fadeIn=Math.min(a.fadeIn||0,a.duration-duration);b.fadeIn=duration;b.fadeOut=Math.min(b.fadeOut||0,b.duration-duration);a.fadeOutCurve=b.fadeInCurve='power';duckActivityCache=null;save();render();return{start,end:audioEnd(a)}}
const clipControlsBeforeCurves=renderClipSettings;renderClipSettings=function(){clipControlsBeforeCurves();const c=tracks().find(c=>c.id===selectedAudio);if(!c)return;for(const [name,key]of [['Fade-in curve','fadeInCurve'],['Fade-out curve','fadeOutCurve']]){const select=storySelect(Object.entries(audioFadeCurves),c[key]||'linear',value=>{if(c.locked)return;c[key]=value;duckActivityCache=null;save();renderTimeline()},name);select.disabled=!!c.locked;const label=document.createElement('label');label.textContent=name;label.append(select);$('clipSettings').append(label)}if(c.role==='narration'){const label=document.createElement('label');label.textContent='Music drop (dB)';const input=storyNumber(c.duckReductionDb??duckSettings().reduction,0,36,value=>{if(c.locked)return;c.duckReductionDb=value;const line=project.scenes.flatMap(storyLines).find(l=>l.audioId===c.id);if(line)line.duckReductionDb=value;duckActivityCache=null;save()},'Narration music reduction');input.disabled=!!c.locked;label.append(input);$('clipSettings').append(label)}const next=tracks().filter(b=>b!==c&&b.start>c.start&&!b.locked);if(next.length){const panel=document.createElement('details');panel.innerHTML='<summary>Crossfade audio</summary><select id="crossfadeNextAudio" aria-label="Crossfade into audio"></select><label>Overlap (s)<input id="crossfadeDuration" type="number" min="0.05" max="30" step="0.05" value="0.5"></label><button id="applyAudioCrossfade">Apply crossfade</button>';$('clipSettings').append(panel);for(const b of next){const option=document.createElement('option');option.value=b.id;option.textContent=b.name;$('crossfadeNextAudio').append(option)}$('applyAudioCrossfade').disabled=!!c.locked;$('applyAudioCrossfade').onclick=()=>{try{crossfadeAudioClips(c,tracks().find(b=>b.id===$('crossfadeNextAudio').value),+$('crossfadeDuration').value)}catch(e){toast(e.message)}}}};
const arrangeBeforeLineDucking=arrangeConversation;arrangeConversation=function(...args){const previous=[];for(const line of storyLines(current())){const c=tracks().find(c=>c.id===line.audioId);if(c&&line.duckReductionDb!==undefined){previous.push([c,c.duckReductionDb]);c.duckReductionDb=line.duckReductionDb}}const result=arrangeBeforeLineDucking(...args);if(!result)for(const[c,value]of previous){if(value===undefined)delete c.duckReductionDb;else c.duckReductionDb=value}duckActivityCache=null;return result};
const storyBeforeLineDucking=renderStoryEditor;renderStoryEditor=function(){storyBeforeLineDucking();for(const row of document.querySelectorAll('.story-line')){const line=storyLines(current()).find(l=>l.id===row.dataset.lineId);if(!line)continue;const label=document.createElement('label');label.textContent='Music drop (dB)';const input=storyNumber(line.duckReductionDb??duckSettings().reduction,0,36,value=>{const c=tracks().find(c=>c.id===line.audioId);if(c?.locked)return;line.duckReductionDb=value;if(c)c.duckReductionDb=value;duckActivityCache=null;save()},'Line music reduction');label.append(input);const reset=storyButton('Use global music drop',()=>{const c=tracks().find(c=>c.id===line.audioId);if(c?.locked)return;delete line.duckReductionDb;if(c)delete c.duckReductionDb;duckActivityCache=null;save();renderStoryEditor()});row.querySelector('.story-line-timing .story-line-controls')?.append(label,reset)}};
// Phrase controls use the installed local engine for each phrase; no SSML or remote service is assumed.
let voicePhraseDraft=[],phraseVoiceCache=new Map();
$('offlineVoiceDelivery').closest('.offline-voice-settings').after(Object.assign(document.createElement('details'),{id:'phraseVoicePanel',innerHTML:'<summary>Phrase pauses & emphasis</summary><label><input id="phraseVoiceEnabled" type="checkbox"> Use phrase controls</label><button id="splitVoicePhrases">Split text into phrases</button><div id="voicePhraseRows"></div><p class="note">Each phrase is generated locally. Emphasis adjusts pace and level; Pause after adds silence. The voice model determines the acting. Keep up to 12 phrases and 60 seconds total.</p>'}));
function splitVoicePhrases(text){const phrases=(text.match(/[^.!?\n]+[.!?]*|\n/gu)||[]).map(s=>s.trim()).filter(Boolean);if(!phrases.length||phrases.length>12)throw Error('Use 1 to 12 phrases, or split the dialogue into shorter lines.');return phrases.map(text=>({text,pause:.15,speed:1,emphasis:'none'}))}
function validVoicePhrases(phrases,text){return Array.isArray(phrases)&&phrases.length>0&&phrases.length<=12&&phrases.every(p=>p&&typeof p.text==='string'&&p.text.length>0&&p.text.length<=2000&&Number.isFinite(p.pause)&&p.pause>=0&&p.pause<=5&&Number.isFinite(p.speed)&&p.speed>=.6&&p.speed<=1.6&&['none','gentle','strong'].includes(p.emphasis))&&phrases.map(p=>p.text).join(' ').replace(/\s+/g,' ').trim()===text.replace(/\s+/g,' ').trim()}
function renderVoicePhrases(){const rows=$('voicePhraseRows');rows.replaceChildren();for(const [i,p]of voicePhraseDraft.entries()){const row=document.createElement('article');row.className='voice-phrase-row';const text=document.createElement('strong');text.textContent=(i+1)+'. '+p.text;row.append(text,storyLabel('Added pause',storyNumber(p.pause,0,5,v=>p.pause=v,'Phrase '+(i+1)+' pause')),storyLabel('Pace',storyNumber(p.speed,.6,1.6,v=>p.speed=v,'Phrase '+(i+1)+' pace')),storyLabel('Emphasis',storySelect(['none','gentle','strong'].map(k=>[k,k]),p.emphasis,v=>p.emphasis=v,'Phrase '+(i+1)+' emphasis')));rows.append(row)}}
$('splitVoicePhrases').onclick=()=>{try{voicePhraseDraft=splitVoicePhrases($('offlineVoiceText').value.trim());$('phraseVoiceEnabled').checked=true;renderVoicePhrases()}catch(e){$('offlineVoiceStatus').textContent=e.message}};
const requestBeforePhraseVoice=offlineVoiceRequest;offlineVoiceRequest=function(){const request=requestBeforePhraseVoice();if($('phraseVoiceEnabled').checked){if(!validVoicePhrases(voicePhraseDraft,request.text))throw Error('The text changed. Split phrases again before previewing.');request.phrases=structuredClone(voicePhraseDraft)}return request};
const openBeforePhraseVoice=openOfflineVoice;openOfflineVoice=async function(line){voicePhraseDraft=structuredClone(line.ttsPhrases||[]);$('phraseVoiceEnabled').checked=!!voicePhraseDraft.length;renderVoicePhrases();return openBeforePhraseVoice(line)};
const chooseBeforePhraseVoice=chooseVoiceTake;chooseVoiceTake=async function(take){voicePhraseDraft=structuredClone(take.request.phrases||[]);$('phraseVoiceEnabled').checked=!!voicePhraseDraft.length;renderVoicePhrases();return chooseBeforePhraseVoice(take)};
const synthBeforePhraseVoice=synthesizeOfflineVoice;synthesizeOfflineVoice=async function(){const request=offlineVoiceRequest();if(!request.phrases)return synthBeforePhraseVoice();const key=JSON.stringify(request);if(offlineVoiceCache?.key===key){$('offlineVoiceAudio').src=offlineVoiceCache.src;return offlineVoiceCache}const generated=[];for(const [index,phrase]of request.phrases.entries()){$('offlineVoiceStatus').textContent='Creating phrase '+(index+1)+' of '+request.phrases.length+' locally…';const settings={text:phrase.text,voice:request.voice,speed:clamp(request.speed*phrase.speed*(phrase.emphasis==='strong'?.92:1),.6,1.6),delivery:request.delivery},cacheKey=JSON.stringify(settings);let buffer=phraseVoiceCache.get(cacheKey);if(!buffer){const response=await fetch('/api/tts',{method:'POST',headers:{'Content-Type':'application/json'},body:cacheKey});if(!response.ok)throw Error((await response.json()).error||'Phrase synthesis failed.');buffer=await decodeFile(await response.blob());phraseVoiceCache.set(cacheKey,buffer);if(phraseVoiceCache.size>24)phraseVoiceCache.delete(phraseVoiceCache.keys().next().value)}generated.push({buffer,gain:phrase.emphasis==='strong'?1.18:phrase.emphasis==='gentle'?.82:1,pause:index===request.phrases.length-1?0:phrase.pause})}const duration=generated.reduce((n,p)=>n+p.buffer.duration+p.pause,0);if(duration>60)throw Error('These phrases exceed 60 seconds. Split the line or shorten its pauses.');const mix=new OfflineAudioContext(1,Math.ceil(duration*44100),44100);let cursor=0;for(const phrase of generated){const source=mix.createBufferSource(),gain=mix.createGain();source.buffer=phrase.buffer;gain.gain.value=phrase.gain;source.connect(gain).connect(mix.destination);source.start(cursor);cursor+=phrase.buffer.duration+phrase.pause}const buffer=await mix.startRendering(),samples=buffer.getChannelData(0);let peak=0;for(const v of samples)peak=Math.max(peak,Math.abs(v));if(peak>.98)for(let i=0;i<samples.length;i++)samples[i]*=.98/peak;const src=await dataURL(wavBlob(buffer));offlineVoiceCache={key,request,src,buffer};voiceTakePreviewId=null;$('offlineVoiceAudio').src=src;$('offlineVoiceAudio').hidden=false;$('offlineVoiceStatus').textContent='Phrase delivery ready · '+duration.toFixed(1)+'s.';return offlineVoiceCache};
const addBeforePhraseVoice=$('addOfflineVoice').onclick;$('addOfflineVoice').onclick=async()=>{const context=offlineVoiceContext;await addBeforePhraseVoice();if(context&&context.project===project&&context.line.audioId){const c=tracks().find(c=>c.id===context.line.audioId);if(c?.src===offlineVoiceCache?.src){if(offlineVoiceCache.request.phrases){c.tts.phrases=structuredClone(offlineVoiceCache.request.phrases);context.line.ttsPhrases=structuredClone(offlineVoiceCache.request.phrases)}else{delete c.tts?.phrases;delete context.line.ttsPhrases}save()}}};
const validBeforeAudioUpgrades=valid;valid=function(p){try{return validBeforeAudioUpgrades(p)&&(p.audioClips||[]).every(c=>['fadeInCurve','fadeOutCurve'].every(k=>c[k]===undefined||Object.hasOwn(audioFadeCurves,c[k]))&&(c.duckReductionDb===undefined||Number.isFinite(c.duckReductionDb)&&c.duckReductionDb>=0&&c.duckReductionDb<=36)&&(!c.tts?.phrases||validVoicePhrases(c.tts.phrases,c.tts.phrases.map(p=>p.text).join(' '))))&&p.scenes.every(s=>storyLines(s).every(l=>(l.duckReductionDb===undefined||Number.isFinite(l.duckReductionDb)&&l.duckReductionDb>=0&&l.duckReductionDb<=36)&&(!l.ttsPhrases||validVoicePhrases(l.ttsPhrases,l.ttsPhrases.map(p=>p.text).join(' ')))&&(!l.voiceTakes||l.voiceTakes.every(t=>!t.request.phrases||validVoicePhrases(t.request.phrases,t.request.text)))))}catch{return false}};
